sys_script_include.script:
var CoursesUtils = Class.create();
CoursesUtils.prototype = {
    initialize: function() {},
    refQualCourses: function() {
        var userId = gs.getUserID(); // Pega o ID do usuário logado
        var coursesAlreadyEnrolled = [];

        // 1. Busque todas as matrículas do usuário em uma única consulta
        var gr = new GlideRecord('x_1593183_traini_0_training_enrollments'); // Substitua pela tabela de matrículas
        gr.addQuery('opened_by', userId);
        gr.addQuery('active', true); // Apenas matrículas ativas
        gr.query();

        // 2. Armazene os cursos aos quais o usuário já se inscreveu
        while (gr.next()) {
            var courseId = gr.course; // Substitua com o campo correto que referencia o curso
            coursesAlreadyEnrolled.push(courseId);
        }

        // 3. Agora, verifique os cursos para os quais o usuário tem menos de 3 matrículas
        var validCourses = [];
        var countEnrollments;

        // 4. Faça uma única consulta para verificar a contagem de matrículas por curso
        var courseGR = new GlideRecord('x_1593183_traini_0_training_courses'); // Tabela dos cursos
        courseGR.addQuery('sys_id', 'IN', coursesAlreadyEnrolled); // Filtra para os cursos válidos
        courseGR.query();

        while (courseGR.next()) {
            var courseToCheckId  = courseGR.sys_id;

            countEnrollments = new GlideRecord('x_1593183_traini_0_training_enrollments'); // Tabela de matrículas
            countEnrollments.addQuery('course', courseToCheckId );
            countEnrollments.addQuery('opened_by', userId);
            countEnrollments.addQuery('active', true); // Matrículas ativas
            countEnrollments.query();

            // Se o usuário tem menos de 3 matrículas para o curso, adicione à lista
            if (countEnrollments.getRowCount() < 3) {
                validCourses.push(courseToCheckId );
            }
        }

        // Retorna a lista de cursos válidos
        return validCourses;
    },



    type: 'CoursesUtils'
};
